  List<String>projection=new ArrayList<>(List.of(repo.resolve("build-tools/RUNTIME_S_TO_R.tsv").toString(),source.toString(),repo.resolve("build-tools/declarations.json").toString(),declaration.toString(),repo.resolve("build-tools/RuntimeOriginalMetadata.json").toString(),out.resolve("runtime-R.jar").toString(),out.resolve("RUNTIME_TRANSPORT.json").toString()));projection.addAll(providers);SourceRuntimeImageAdapter.main(projection.toArray(String[]::new));
  RuntimeArchiveAudit.main(new String[]{out.resolve("runtime-R.jar").toString(),repo.resolve("build-tools/RuntimeRDeclarations.json").toString(),out.resolve("RUNTIME_TRANSPORT.json").toString(),out.resolve("RUNTIME_IDENTITY.json").toString()});
