  JsonObject result=new JsonObject();result.addProperty("status","verified_source_derived_uid_free_R_client_manual_function_acceptance_pending");result.addProperty("source_S_archive",source.toString());result.addProperty("source_S_sha256",sha(source));result.addProperty("runtime_R_archive",out.resolve("runtime-R.jar").toString());result.addProperty("runtime_R_sha256",sha(out.resolve("runtime-R.jar")));result.addProperty("client_archive",client.toString());result.addProperty("client_sha256",sha(client));result.addProperty("static_member_failures",read(out.resolve("RUNTIME_MEMBER_CLOSURE.json")).get("failure_count").getAsInt());result.addProperty("owned_classes",contract.get("expected_owned_classes").getAsInt());result.addProperty("uid_verification_included",false);result.addProperty("original_behavior_equivalence_claimed",false);result.addProperty("provider_count",providers.size());result.addProperty("resource_entries",contract.get("expected_resource_entries").getAsInt());result.addProperty("JVM_class_failures",read(out.resolve("JVM_CLASSES.json")).get("failed").getAsInt());result.addProperty("JVM_client_failures",read(out.resolve("JVM_CLIENT.json")).get("failed").getAsInt());result.addProperty("application_initialization_requested",false);result.addProperty("client_executed",false);Files.writeString(out.resolve("CLIENT_DELIVERY.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result),StandardOpenOption.CREATE_NEW);System.out.println(client);
